UPDATE companies SET description='Tin Man Duct Fabrication, based in Manassas, Virginia, has been producing SMACNA-compliant ductwork since 2001. The company serves the greater Washington, D.C. metro area, including Virginia, Maryland, the District, Delaware, and eastern West Virginia.

The shop operates multiple automated production lines to fabricate a full range of ductwork—spiral pipe and fittings, flat oval, TDC, welded stainless, curb adapters, roof rails, and fiberglass-lined products—in materials such as galvanized steel, stainless steel, aluminum, and black iron. Every fitting is inspected and signed by a quality technician before it leaves the facility. The company handles orders from a single fitting up to 400,000-pound projects and delivers to job sites across the region.

Tin Man supplies commercial, industrial, residential, and government contractors. Its customer base includes mechanical contractors who use the shop as a backup when their own fabrication capacity is maxed out, as well as projects requiring LEED-compliant ductwork.

The company differentiates itself by focusing exclusively on ductwork fabrication, avoiding competition with installation contractors. A computerized pricing system provides consistent quotes, and the shop emphasizes fast turnaround, including same-day service on emergency orders.', certifications=ARRAY['LEED']::text[], profile='{"capabilities": ["Spiral pipe and fittings fabrication (slip joint, gasketed, flanged)", "Long seam flat oval pipe and fittings fabrication", "TDC ductwork fabrication", "Welded stainless steel fabrication", "Curb adapter fabrication", "Roof rail / equipment rail fabrication", "Doghouse fabrication", "ManBar / burglar bar fabrication", "CAD services and shop drawings & as-builts", "Fiberglass R-rated liner installation", "Delivery to job sites", "SMACNA-compliant fabrication"], "industries": ["Commercial construction", "Industrial", "Residential", "Government"], "materials": ["G90 galvanized steel", "Stainless steel", "Aluminum", "Black iron", "Fiberglass R-rated liner"], "equipment": [], "volume": "One fitting to 400,000-pound jobs", "lead_time": "Fast turnaround; same-day for emergency orders", "tolerances": "", "built_on": ["Every fitting inspected and signed by a quality technician", "Exclusive ductwork fabrication \u2014 no installation competition", "Computerized pricing for consistent, competitive quotes", "Same-day turnaround on emergency orders"], "facts_used": ["Founded 2001 -> db and / page", "Headquarters Manassas, Virginia -> db and / page", "SMACNA-compliant ductwork -> / page", "Serves VA, MD, DC, DE, Eastern WV -> / page", "Multiple automated production lines -> / page", "Quality technician inspects and signs every fitting -> / page", "Computerized pricing system -> / page", "Handles one fitting to 400,000 lb jobs -> / page", "Materials: galvanized, stainless, aluminum, black iron, fiberglass liner -> /services page", "Services: spiral, flat oval, TDC, welded stainless, curb adapters, roof rails, doghouses, ManBars, CAD, delivery -> /services page", "Industries: commercial, industrial, residential, government -> / page", "LEED certification -> db", "Fast turnaround, same-day emergency orders -> / page and testimonial", "Exclusive ductwork fabrication, no installation -> / page"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "We only fabricate ductwork, so we do not compete with our customers.", "founded_year": "2001", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='tin-man-duct-fabrication' AND approved AND profile IS NULL;
UPDATE companies SET description='The business is owned and run by Tom Simmons, who works directly with clients on custom cabinetry projects.

The shop fabricates custom kitchen cabinets, bathroom vanities, and built-in furniture pieces. Each project is tailored to the client''s specifications, with an emphasis on fit, finish, and integration into existing home architecture.

