UPDATE companies SET description='True Position Plastics, LLC is based in Duncan, Oklahoma. The company was founded by Justin Church, a tooling and mold design expert with over 25 years of hands-on experience in the plastics industry. Church began his career as a machinist and mold maker, spending more than a decade as a mold designer before advancing to Tooling Manager and Tooling Engineer roles where he led complex programs from concept through production.

The firm provides plastic injection molding services sourced from both domestic and overseas tooling partners, managing the full process from mold construction to production parts. Its service portfolio includes scientific molding, liquid silicone rubber (LSR) molding, insert molding, overmolding, CNC machining, and comprehensive mold design for prototype and production molds (SPI Class 101–105). The company also offers mold flow analysis and SimForm cooling analysis to optimize part and tool design before steel is cut, reducing cycle time and improving part consistency.

True Position Plastics serves customers in the medical, consumer, automotive, industrial, and telecommunications sectors.

The company emphasizes its ability to bridge design and manufacturing, drawing on experience from hundreds of injection molds across multiple industries. This insight allows the team to guide customers early in development, saving time and cost while improving tool longevity. By leveraging a network of global tooling partners, True Position Plastics aims to deliver high-quality molds and reliable production at competitive cost.', certifications=ARRAY['ISO9001','ISO13485','ITAR']::text[], profile='{"capabilities": ["Plastic Injection Molding", "Scientific Molding", "Mold Design", "Mold Flow Analysis", "SimForm Cooling Analysis", "CNC Machining", "LSR Molding", "Insert Molding", "Overmolding", "DFM Review", "Mold Classification (SPI Class 101\u2013105)"], "industries": ["Medical", "Consumer", "Automotive", "Industrial", "Telecommunications"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Manages entire mold-to-part process through trusted global tooling partners", "Full mold design services for prototype and production molds (SPI Class 101\u2013105)", "Mold flow analysis and SimForm cooling analysis to optimize designs before steel cut", "Experience across hundreds of molds in medical, consumer, and industrial applications", "Early development guidance to reduce time, cost, and improve tool longevity"], "facts_used": ["Company name and location -> db", "Founder Justin Church and background -> db", "Certifications ISO9001, ISO13485, ITAR -> db", "Capabilities: plastic injection molding, scientific molding, mold design, mold flow analysis, SimForm cooling analysis, CNC machining, LSR molding, insert molding, overmolding -> db and /about-us", "Industries served: medical, consumer, automotive, industrial, telecommunications -> / and /about-us", "Services: manages entire process from mold build to production parts using global tooling partners -> / and /about-us", "Mold design for SPI Class 101-105 -> /about-us", "Mold flow analysis and cooling analysis to optimize design before steel cut -> /about-us", "Experience across hundreds of injection molds -> /about-us", "Guidance early in development to save time and cost -> /about-us"], "company_type": "Contract manufacturer / job shop", "makes_products": "unclear", "type_evidence": "We manage the entire process from mold build to production parts using our trusted global tooling partners.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": ["ITAR registered"], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='true-position-plastics-llc' AND approved AND profile IS NULL;
UPDATE companies SET description='True Weld Metal Fabrication operates from Aurora, Colorado, serving the Denver metropolitan area. The family-owned shop traces its roots to a home garage where the founder began welding more than two decades ago, eventually expanding into a mobile-and-shop operation that covers residential, commercial, and agricultural sites across the region.

The company provides on-site mobile welding and in-shop custom fabrication, working with mild steel, aluminum, and stainless steel. Services include structural welding for beams, columns, and mezzanines; trailer and equipment repairs; custom gates, fences, and handrails; and code-conscious structural fabrication. The owner-operator performs every weld, with no subcontracting, and the shop handles both one-off pieces and repeat production for commercial clients.

Customers range from homeowners needing driveway gates or trailer hitch repairs to warehouses requiring mezzanine structural work and farms with equipment breakdowns. Recent projects cited include a 9 p.m. emergency trailer repair in Aurora, a custom driveway gate in Parker, and structural repairs on a Denver warehouse mezzanine.

True Weld emphasizes 24/7 mobile response, certified welding practices across all three material groups, full liability and workers'' compensation coverage, and a warranty on workmanship. Pricing is quoted over the phone with no surprises, and the company maintains OSHA-conscious job-site practices.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Mobile welding (on-site)", "Structural welding (beams, columns, mezzanines, code-conscious)", "Custom metal fabrication (gates, handrails, trailers, brackets)", "Aluminum welding (TIG & MIG)", "Steel fabrication (mild and heavy plate, tube, section)", "Stainless steel welding (food-grade, architectural)", "Trailer repairs (frame, hitch, deck, axle)", "Fence and gate fabrication (custom driveway gates, ornamental fencing, security gates)", "Handrail fabrication and installation", "Equipment repairs (cracked buckets, broken frames, worn hitches)", "Commercial welding (retail, warehouse, industrial)", "Residential welding", "Weld repairs", "Code-conscious structural fabrication"], "industries": ["Residential", "Commercial", "Industrial", "Agricultural", "Retail", "Warehouse", "Construction"], "materials": ["Mild steel", "Steel plate", "Steel tube", "Steel section", "Aluminum", "Stainless steel"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["24/7 mobile welding response across the Denver metro", "Owner-operator on every job, no subcontractors", "Certified welding practices across mild steel, aluminum, and stainless steel", "Full liability insurance and workers'' compensation coverage on commercial sites", "Warranty on workmanship with straight-talk pricing quoted by phone"], "facts_used": ["Aurora, Colorado headquarters -> db", "Family-owned -> db, /, /about", "20+ years welding experience -> /, /about", "Started in home garage -> /about", "Mobile welding service across Denver metro -> /, /services", "Structural welding (beams, columns, mezzanines, code-conscious) -> /, /services